```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "An OWL ontology modelling securities, debt, equity, hybrid, derivative and fund instruments as described in the supplied corpus (Wikipedia-style articles, ECB glossary, IAS/IFRS material, FINRA/CFI/OpenStax glossaries)." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "financial instrument" ;
    rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled; e.g. cash, evidence of ownership, debt, equity or derivatives (IAS 32 / corpus)." .

fis:Underlier a owl:Class ;
    rdfs:label "underlier" ;
    rdfs:comment "An item (asset, rate, index, currency or event) that can or must be bought, sold, or referenced by a derivative or other contingent instrument." .

fis:FinancialInstrument rdfs:subClassOf fis:Underlier .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "commodity" .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "currency" .
fis:Index a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "index" .
fis:InterestRateIndex a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "interest rate" .
fis:CreditEvent a owl:Class ; rdfs:subClassOf fis:Underlier ;
    rdfs:comment "A measurable occurrence, such as a default, on which a derivative's value may depend." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "cash instrument" ;
    rdfs:comment "An instrument whose value is determined directly by the markets (e.g. a security, a loan, a deposit)." .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "derivative" , "derivative instrument" ;
    rdfs:comment "A contract that derives its value from the performance of one or more underliers; has four elements: an underlier, a required future act, an agreed price, and a future date." .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:Derivative ) ] .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "security" ;
    rdfs:comment "A tradable financial asset; readily transferable. NOTE: the US definition of 'security' broadly also includes derivatives (forwards, futures, options, swaps) as one of three security categories, conflicting with the structural model used here, where Derivative is modelled as a sibling of CashInstrument rather than a subclass of Security; this conflict is noted per corpus." .

fis:Loan a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "loan" ;
    rdfs:comment "A cash instrument, such as a loan or deposit, requiring agreement of both borrower and lender to transfer, unlike a security which is readily transferable." .

owl:AllDisjointClasses [ owl:members ( fis:Security fis:Loan ) ] .

#################################################################
# ISSUERS AND HOLDERS
#################################################################

fis:Issuer a owl:Class ; rdfs:label "issuer" ;
    rdfs:comment "The entity which is obligated on, or which issues, a security or other financial instrument." .

fis:Government a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "government" .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Government ; rdfs:label "sovereign government" .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Government ;
    rdfs:label "local government" , "municipality" ;
    rdfs:comment "State, provincial, territorial, municipal or other sub-sovereign governmental unit." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "corporation" .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
    rdfs:label "supranational organization" ;
    rdfs:comment "E.g. World Bank, IMF, regional multilateral development banks." .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "bank" .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:Corporation fis:SupranationalOrganization ) ] .

fis:Holder a owl:Class ; rdfs:label "holder" ;
    rdfs:comment "An entity entitled to rights under a security by virtue of possession or registration." .

fis:Shareholder a owl:Class ;
    rdfs:label "shareholder" , "stockholder" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Holder
        [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:Stock ] ) ] .

fis:Bondholder a owl:Class ;
    rdfs:label "bondholder" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Holder
        [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:Bond ] ) ] .

#################################################################
# IAS 32 / IFRS 9 ACCOUNTING CLASSIFICATION (layered over instrument taxonomy)
#################################################################

fis:FinancialAsset a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "financial asset" ;
    rdfs:comment "IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash/another financial asset, or a contractual right to exchange financial instruments under potentially favourable conditions." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasContractualRightToReceiveCash ; owl:hasValue true ] ) ] .

fis:FinancialLiability a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "financial liability" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToDeliverCash ; owl:hasValue true ] ) ] .

fis:EquityInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "equity instrument" ;
    rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToDeliverCash ; owl:hasValue false ]
        [ a owl:Restriction ; owl:onProperty fis:representsResidualInterest ; owl:hasValue true ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:FinancialLiability fis:EquityInstrument ) ] .

fis:AmortizedCostFinancialAsset a owl:Class ;
    rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "amortised cost financial asset" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
        [ a owl:Restriction ; owl:onProperty fis:passesSPPITest ; owl:hasValue true ]
        [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:hasValue "holdToCollect" ] ) ] .

fis:FVOCIFinancialAsset a owl:Class ;
    rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "fair value through OCI financial asset" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
        [ a owl:Restriction ; owl:onProperty fis:passesSPPITest ; owl:hasValue true ]
        [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:hasValue "holdToCollectAndSell" ] ) ] .

fis:FVTPLFinancialAsset a owl:Class ;
    rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "fair value through profit or loss financial asset" ;
    rdfs:comment "Residual measurement category; includes all derivative financial assets (which fail the SPPI test) and equity investments without the FVOCI election." .

owl:AllDisjointClasses [ owl:members ( fis:AmortizedCostFinancialAsset fis:FVOCIFinancialAsset fis:FVTPLFinancialAsset ) ] .

#################################################################
# MAIN SECURITY CATEGORIES
#################################################################

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security , fis:FinancialLiability ;
    rdfs:label "debt security" ;
    rdfs:comment "Holder entitled to payment of principal and interest; called debentures, bonds, deposits, notes or commercial paper depending on maturity, collateral and other characteristics." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToDeliverCash ; owl:hasValue true ] ) ] .

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security , fis:EquityInstrument ;
    rdfs:label "equity security" ;
    rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; residual claim after creditors." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToDeliverCash ; owl:hasValue false ]
        [ a owl:Restriction ; owl:onProperty fis:representsResidualInterest ; owl:hasValue true ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity ) ] .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "hybrid security" ;
    rdfs:comment "Combines characteristics of both debt and equity securities (e.g. preference shares, convertibles, equity warrants); not disjoint with DebtSecurity or EquitySecurity, since e.g. convertible bonds are both debt securities and hybrid securities." .

#################################################################
# OWNERSHIP FORM (Security level)
#################################################################

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "bearer security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "bearer" ] ) ] .

fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "registered security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "registered" ] ) ] .

fis:BookEntrySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "book-entry security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "book-entry" ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) ] .

#################################################################
# BONDS AND OTHER DEBT SECURITIES
#################################################################

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "bond" ;
    rdfs:comment "A security under which the issuer (debtor) owes the holder (creditor) a debt and is obliged to repay the principal at maturity plus interest (coupon); generally longer-term than money market instruments." .

fis:Debenture a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "debenture" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue false ] ) ] ;
    rdfs:comment "Unsecured debt security with only a general claim on the issuer's assets; corpus also mentions a conflicting characterisation of debentures as simply long-maturity (>=10 yr) corporate bonds distinguished from shorter-maturity notes - both notions retained in comment." .

fis:Note a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "note" ;
    rdfs:comment "Debt security with shorter maturity than a debenture." .

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "money market instrument" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasMaturityPeriodInDays ;
          owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                                owl:withRestrictions ( [ xsd:maxInclusive 365 ] ) ] ] ) ] ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less." .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "commercial paper" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue false ]
        [ a owl:Restriction ; owl:onProperty fis:hasMaturityPeriodInDays ;
          owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                                owl:withRestrictions ( [ xsd:maxExclusive 270 ] ) ] ] ) ] ;
    rdfs:comment "Unsecured promissory note with a fixed maturity of usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "certificate of deposit" , "CD" ;
    rdfs:comment "Time deposit sold by banks, thrift institutions and credit unions, with a specific fixed term." .

fis:EuroDebtSecurity a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "euro debt security" , "eurobond" , "euronote" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:isIssuedOutsideDomesticMarket ; owl:hasValue true ] ) ] ;
    rdfs:comment "Issued internationally outside the issuer's domestic market in a denomination different from that of the issuer's domicile." .

#### Issuer-based bond classification

fis:GovernmentBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "government bond" , "sovereign bond" , "treasury bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "municipal bond" , "muni" , "sub-sovereign government bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:CorporateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "corporate bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:SupranationalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "supranational bond" , "supra" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:MunicipalBond fis:CorporateBond fis:SupranationalBond ) ] .

fis:GeneralObligationBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "general obligation bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:isBackedByFullFaithAndCredit ; owl:hasValue true ] ) ] .

fis:RevenueBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "revenue bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:isBackedByFullFaithAndCredit ; owl:hasValue false ] ) ] ;
    rdfs:comment "Repayment guaranteed solely from revenues of a specified revenue-generating project; typically non-recourse." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "gilt" ; rdfs:comment "UK government bond." .

fis:TreasuryBill a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond , fis:MoneyMarketInstrument ;
    rdfs:label "treasury bill" , "T-bill" .

fis:TreasuryNote a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond , fis:Note ;
    rdfs:label "treasury note" ; rdfs:comment "US Treasury security with maturity of two to ten years." .

fis:TreasuryBond a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "treasury bond (long bond)" ; rdfs:comment "US Treasury security with maturity of twenty to thirty years." .

fis:TreasuryInflationProtectedSecurity a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "Treasury Inflation-Protected Security" , "TIPS" .

#### Coupon-type classification

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "fixed rate bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "fixed" ] ) ] .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "floating rate note" , "FRN" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "floating" ] ) ] .

fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "zero-coupon bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "zero" ] ) ] ;
    rdfs:comment "Face value repaid at maturity with no periodic interest; issued at a substantial discount to par." .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "inflation-indexed bond" , "linker" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isIndexedToInflation ; owl:hasValue true ] ) ] .

#### Ownership-form bonds

fis:BearerBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
    rdfs:label "bearer bond" .

fis:RegisteredBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] ;
    rdfs:label "registered bond" .

fis:BookEntryBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BookEntrySecurity ) ] ;
    rdfs:label "book-entry bond" .

#### Embedded-option bonds

fis:CallableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "callable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue true ] ) ] .

fis:PutableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "putable bond" , "retractable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue true ] ) ] .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "bullet bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue false ]
        [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue false ] ) ] ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "perpetual bond" , "perpetuity" , "irredeemable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxQualifiedCardinality "0"^^xsd:nonNegativeInteger ; owl:onDataRange xsd:date ] ) ] ;
    rdfs:comment "Exception to the general bond pattern of having a stated maturity date; has no maturity date." .

#### Credit-quality bonds

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "investment grade bond" , "high grade bond" ;
    rdfs:comment "Rated AAA, AA, A or BBB by credit rating agencies." .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "high-yield bond" , "junk bond" ;
    rdfs:comment "Rated below investment grade (BB and below)." .

owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

#### Convertible bond (hybrid)

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:Bond , fis:HybridSecurity ;
    rdfs:label "convertible bond" , "convertible note" , "convertible debenture" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "Lets the bondholder exchange the bond for a specified number of shares of the issuer's common stock." .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "asset-backed security" , "ABS" ;
    rdfs:comment "CONFLICT noted in corpus: 'asset-backed security' is sometimes an umbrella term for any security backed by a pool of assets (including MBS and CDO as subsets), and sometimes a narrower term for securities backed specifically by consumer loans/receivables other than real estate, distinct from MBS/CDO. This ontology models the broader (majority/structurally dominant) sense as fis:AssetBackedSecurity, with the narrower sense captured by fis:ConsumerAssetBackedSecurity." .

fis:ConsumerAssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "consumer asset-backed security" ;
    rdfs:comment "Narrow sense of ABS: backed by consumer loans, leases or receivables other than real estate (auto loans, credit cards, student loans, home equity loans)." .

fis:HomeEquityLoanABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ;
    rdfs:label "home equity loan ABS" , "HEL" .
fis:AutoLoanABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ;
    rdfs:label "auto loan ABS" .
fis:CreditCardReceivableABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ;
    rdfs:label "credit card receivable ABS" .
fis:StudentLoanABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ;
    rdfs:label "student loan ABS" , "SLABS" .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "collateralized debt obligation" , "CDO" ;
    rdfs:comment "Structured ABS backed by debt obligations, often other asset-backed securities; sliced into tranches by seniority." .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "mortgage-backed security" , "MBS" ;
    rdfs:comment "ABS secured by a mortgage or pool of mortgages." .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "residential mortgage-backed security" , "RMBS" ;
    rdfs:comment "Secured by single-family, one- to four-unit real estate." .

fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "commercial mortgage-backed security" , "CMBS" ;
    rdfs:comment "Secured by commercial and multi-family properties." .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "pass-through security" ;
    rdfs:comment "Allocates cash flows from the underlying pool to holders on a pro rata basis." .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "collateralized mortgage obligation" , "CMO" , "pay-through bond" .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "stripped mortgage-backed security" , "SMBS" .

fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:label "interest-only strip" , "IO" .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:label "principal-only strip" , "PO" .

owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "depositary receipt" , "DR" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ]
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "Negotiable instrument issued by a bank to represent a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American depositary receipt" , "ADR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "European depositary receipt" , "EDR" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "global depositary receipt" , "GDR" .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# EQUITY SECURITIES: STOCK
#################################################################

fis:Stock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "stock" , "share" , "capital stock" ;
    rdfs:comment "Consists of all shares by which ownership of a corporation is divided; a single share represents fractional ownership." .

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "common stock" , "ordinary share" , "voting share" ;
    rdfs:comment "Typically carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:Stock , fis:HybridSecurity ;
    rdfs:label "preferred stock" , "preference share" , "preferred share" ;
    rdfs:comment "Senior to common stock but subordinate to bonds; generally considered a hybrid instrument; typically does not carry voting rights but has priority on dividends and liquidation." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "cumulative preferred stock" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue true ] ) ] .

fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "noncumulative preferred stock" , "straight preferred stock" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue false ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "convertible preferred stock" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

#################################################################
# WARRANTS (hybrid, option-like, company-issued)
#################################################################

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:Option , fis:HybridSecurity ;
    rdfs:label "warrant" , "equity warrant" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
    rdfs:comment "Long-dated option issued by the company itself allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "lock product" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToTransact ; owl:hasValue true ] ) ] ;
    rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .

fis:OptionProduct a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "option product" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToTransact ; owl:hasValue false ] ) ] ;
    rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .

owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:LockProduct ;
    rdfs:label "forward" , "forward contract" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
    rdfs:comment "Non-standardized, tailored contract between two parties to buy/sell an asset at a specified future time at today's pre-determined price." .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:LockProduct ;
    rdfs:label "future" , "futures contract" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ] ) ] ;
    rdfs:comment "Standardized contract written by a clearing house that operates an exchange where the contract can be bought and sold." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:OptionProduct ;
    rdfs:label "option" ;
    rdfs:comment "Gives the buyer the right, but not the obligation, to buy (call) or sell (put) an underlying asset at a strike price on or before a specified date." .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:LockProduct ;
    rdfs:label "swap" ;
    rdfs:comment "Two counterparties exchange cash flows of one financial instrument for those of another over a notional principal amount." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) ] .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "call option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] .

fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "put option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "American option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
    rdfs:comment "May be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "European option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
    rdfs:comment "May only be exercised on expiry." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption ) ] .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "interest rate swap" .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "currency swap" .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap ) ] .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "credit default swap" , "CDS" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
    rdfs:comment "Seller compensates the buyer in the event of a loan default or other credit event on the reference entity's debt." .

fis:StockFuture a owl:Class ; rdfs:subClassOf fis:Future ;
    rdfs:label "stock future" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:StockOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "stock option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:ExchangeTradedDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "exchange-traded derivative" , "ETD" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] .

fis:OverTheCounterDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "over-the-counter derivative" , "OTC derivative" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) ] .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "investment fund" ;
    rdfs:comment "Pools money from many investors to purchase securities; the combined holdings are its portfolio." .

fis:MutualFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "mutual fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
    rdfs:comment "Open-end fund purchased from or redeemed to the issuer at net asset value." .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "exchange-traded fund" , "ETF" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
    rdfs:comment "Investors buy and sell ETF shares on national securities exchanges at market prices that may differ from net asset value." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund ) ] .

fis:HedgeFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "hedge fund" ;
    rdfs:comment "Pools investor money like a mutual fund but with few regulations protecting investors and more flexible/risky strategies; available only to high-net-worth individuals." .

fis:EquityFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "equity fund" , "stock fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "bond fund" , "fixed income fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:DebtSecurity ] ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "money market fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .

fis:HybridFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "hybrid fund" , "balanced fund" ;
    rdfs:comment "Invests in a combination of equity and debt securities." .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "index fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Index ] ) ] ;
    rdfs:comment "Passively managed fund that tracks the performance of a stock or bond market index." .

fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "actively managed fund" ;
    rdfs:comment "Seeks to outperform market indices via active security selection; generally charges higher fees than index funds." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Issuer ;
    rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:FinancialInstrument ;
    rdfs:label "is issuer of" .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Holder ;
    rdfs:label "has holder" .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Holder ;
    rdfs:range fis:Security ;
    rdfs:label "is holder of" .

fis:hasUnderlying a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Underlier ;
    rdfs:label "has underlying" .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlier ;
    rdfs:range fis:FinancialInstrument ;
    rdfs:label "is underlying of" .

fis:hasConversionTarget a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range fis:EquitySecurity ;
    rdfs:label "has conversion target" .

fis:isConversionTargetOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasConversionTarget ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:HybridSecurity ;
    rdfs:label "is conversion target of" .

fis:hasReferenceEntity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:Issuer ;
    rdfs:label "has reference entity" .

fis:isReferenceEntityOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasReferenceEntity ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:CreditDefaultSwap ;
    rdfs:label "is reference entity of" .

fis:hasPortfolioHolding a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security ;
    rdfs:label "has portfolio holding" .

fis:isPortfolioHoldingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasPortfolioHolding ;
    rdfs:domain fis:Security ;
    rdfs:range fis:InvestmentFund ;
    rdfs:label "is portfolio holding of" .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date ;
    rdfs:label "has maturity date" .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:decimal ;
    rdfs:label "has face value" , "has par value" , "has nominal amount" .

fis:hasCouponRate a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate" .

fis:hasCouponType a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:string ;
    rdfs:label "has coupon type" ;
    rdfs:comment "One of: fixed, floating, zero." .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:label "has strike price" .

fis:hasExpirationDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:date ;
    rdfs:label "has expiration date" .

fis:hasCollateral a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:boolean ;
    rdfs:label "has collateral" ;
    rdfs:comment "True if the debt security is secured by collateral; false if unsecured." .

fis:isIndexedToInflation a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean ;
    rdfs:label "is indexed to inflation" .

fis:isIssuedOutsideDomesticMarket a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:boolean ;
    rdfs:label "is issued outside domestic market" .

fis:hasOwnershipForm a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string ;
    rdfs:label "has ownership form" ;
    rdfs:comment "One of: bearer, registered, book-entry." .

fis:isCallable a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean ;
    rdfs:label "is callable" .

fis:isPutable a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean ;
    rdfs:label "is putable" .

fis:isBackedByFullFaithAndCredit a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:MunicipalBond ;
    rdfs:range xsd:boolean ;
    rdfs:label "is backed by full faith and credit" .

fis:isStandardized a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean ;
    rdfs:label "is standardized" .

fis:isExchangeTraded a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:boolean ;
    rdfs:label "is exchange traded" .

fis:hasObligationToTransact a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean ;
    rdfs:label "has obligation to transact" ;
    rdfs:comment "True for lock products (forwards, futures, swaps); false for option products." .

fis:hasOptionType a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:string ;
    rdfs:label "has option type" ;
    rdfs:comment "One of: call, put." .

fis:hasExerciseStyle a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:string ;
    rdfs:label "has exercise style" ;
    rdfs:comment "One of: American, European, Bermudan." .

fis:hasMaturityPeriodInDays a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:integer ;
    rdfs:label "has maturity period in days" .

fis:isCumulative a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:boolean ;
    rdfs:label "is cumulative" .

fis:hasVotingRights a owl:DatatypeProperty ;
    rdfs:domain fis:Stock ;
    rdfs:range xsd:boolean ;
    rdfs:label "has voting rights" .

fis:hasObligationToDeliverCash a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:boolean ;
    rdfs:label "has obligation to deliver cash" ;
    rdfs:comment "IAS 32 criterion distinguishing a financial liability (true) from an equity instrument (false)." .

fis:hasContractualRightToReceiveCash a owl:DatatypeProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:boolean ;
    rdfs:label "has contractual right to receive cash" .

fis:representsResidualInterest a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:boolean ;
    rdfs:label "represents residual interest" .

fis:passesSPPITest a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialAsset ;
    rdfs:range xsd:boolean ;
    rdfs:label "passes SPPI test" ;
    rdfs:comment "IFRS 9: contractual cash flows are solely payments of principal and interest." .

fis:hasBusinessModel a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialAsset ;
    rdfs:range xsd:string ;
    rdfs:label "has business model" ;
    rdfs:comment "One of: holdToCollect, holdToCollectAndSell, other." .

fis:hasCreditRating a owl:DatatypeProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:string ;
    rdfs:label "has credit rating" .

fis:hasDividendRate a owl:DatatypeProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has dividend rate" ;
    rdfs:comment "Discretionary distribution of a company's profit to shareholders; unlike a bond coupon, payment is not contractually guaranteed." .
